package dev.ethanyap.slotted.booking.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;

/**
 * A student waiting for an exact slot (BR-24). Every change happens while the room is locked
 * (ADR-0007), so an entry cannot be promoted and left at the same time. The {@code slot} range
 * column is generated by the database, so it is not mapped here.
 */
@Entity
@Table(name = "waitlist_entry")
public class WaitlistEntry {

  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  private UUID id;

  private UUID roomId;
  private UUID userId;
  private Instant startAt;
  private Instant endAt;

  @Enumerated(EnumType.STRING)
  private WaitlistStatus status;

  private UUID promotedBookingId;
  private Instant createdAt;
  private Instant resolvedAt;

  protected WaitlistEntry() {}

  /**
   * Joins the queue.
   *
   * @param joinedAt the queue order (BR-25); taken while the room is locked, so it follows the
   *     order people really joined in
   */
  public WaitlistEntry(UUID roomId, UUID userId, Instant startAt, Instant endAt, Instant joinedAt) {
    this.roomId = roomId;
    this.userId = userId;
    this.startAt = startAt;
    this.endAt = endAt;
    this.status = WaitlistStatus.WAITING;
    this.createdAt = joinedAt;
  }

  /** Status at {@code now}, derived from stored facts (ADR-0004, BR-28). */
  public WaitlistStatus effectiveStatus(Instant now) {
    return status == WaitlistStatus.WAITING && !startAt.isAfter(now)
        ? WaitlistStatus.EXPIRED
        : status;
  }

  public boolean isWaitingAt(Instant now) {
    return effectiveStatus(now) == WaitlistStatus.WAITING;
  }

  public void markPromoted(UUID bookingId, Instant now) {
    status = WaitlistStatus.PROMOTED;
    promotedBookingId = bookingId;
    resolvedAt = now;
  }

  public void markExpired(Instant now) {
    status = WaitlistStatus.EXPIRED;
    resolvedAt = now;
  }

  public void markCancelled(Instant now) {
    status = WaitlistStatus.CANCELLED;
    resolvedAt = now;
  }

  public UUID getId() {
    return id;
  }

  public UUID getRoomId() {
    return roomId;
  }

  public UUID getUserId() {
    return userId;
  }

  public Instant getStartAt() {
    return startAt;
  }

  public Instant getEndAt() {
    return endAt;
  }

  public UUID getPromotedBookingId() {
    return promotedBookingId;
  }

  public Instant getCreatedAt() {
    return createdAt;
  }
}
